def test_test_ref_is_preserved_unchanged() -> None:
    test_ref = "/custom/provider/tests/example/versions/latest?mode=preview"

    step = ValidationStep.test(name="custom", test_ref=test_ref)

    plan = ExecutionPlanConfiguration(
        name="custom-plan",
        certification_package_reference=_package_reference(),
        steps=[step],
    )
    assert json.loads(plan.to_json())["authoring"]["steps"][0]["testRef"] == test_ref


@pytest.mark.parametrize(
    ("factory", "error_type", "message"),
    [
        (
            lambda: ValidationStep.test(name="", test_ref="/tests/example"),
            ValueError,
            "name must not be empty",
        ),
        (
            lambda: ValidationStep.test(name="example", test_ref=42),
            TypeError,
            "test_ref must be a string",
        ),
        (
            lambda: ValidationStep.test(
                name="example", test_ref="/tests/example", inputs=[]
            ),
            TypeError,
            "inputs must be a mapping",
        ),
        (
            lambda: ExecutionPlanConfiguration(
                name="plan",
                certification_package_reference=_package_reference(),
                steps=[],
            ),
            ValueError,
            "steps must contain at least one ValidationStep",
        ),
        (
            lambda: CertificationPackageReference(
                os_type="Linux",
                vm_generation_type="V1",
                architecture_type="X64",
                recommended_vm_sizes="Standard_D4s_v3",
                storage_profile=StorageProfile(
                    os_disk_image=DiskImage(
                        source_vhd_uri="https://contoso.example/img.vhd"
                    )
                ),
            ),
            TypeError,
            "recommended_vm_sizes must be a sequence of strings",
        ),
        (
            lambda: CertificationPackageReference(
                os_type="Linux",
                vm_generation_type="V1",
                architecture_type="X64",
                recommended_vm_sizes=[],
                storage_profile=StorageProfile(
                    os_disk_image=DiskImage(
                        source_vhd_uri="https://contoso.example/img.vhd"
                    )
                ),
            ),
            ValueError,
            "recommended_vm_sizes must contain at least one value",
        ),
    ],
)
def test_invalid_required_values_raise_clear_errors(
    factory, error_type, message
) -> None:
    with pytest.raises(error_type, match=message):
        factory()


def test_to_json_rejects_non_json_serializable_input() -> None:
    plan = ExecutionPlanConfiguration(
        name="plan",
        certification_package_reference=_package_reference(),
        steps=[
            ValidationStep.test(
                name="example",
                test_ref="/tests/example",
                inputs={"value": object()},
            )
        ],
    )

    with pytest.raises(
        TypeError, match="execution plan values must be JSON serializable"
    ):
        plan.to_json()


@pytest.mark.parametrize("non_finite_value", [nan, inf, -inf])
def test_to_json_rejects_non_finite_numbers(non_finite_value: float) -> None:
    plan = ExecutionPlanConfiguration(
        name="plan",
        certification_package_reference=_package_reference(),
        steps=[
            ValidationStep.test(
                name="example",
                test_ref="/tests/example",
                inputs={"value": non_finite_value},
            )
        ],
    )

    with pytest.raises(
        TypeError, match="execution plan values must be JSON serializable"
    ):
        plan.to_json()


def test_frozen_dataclass_mappings_cannot_be_mutated() -> None:
    inputs = {"concurrency": 1}
    additional_properties = {"publisher": "contoso"}
    step = ValidationStep.test(name="example", test_ref="/tests/example", inputs=inputs)
    package_reference = CertificationPackageReference(
        os_type="Linux",
        vm_generation_type="V1",
        architecture_type="X64",
        recommended_vm_sizes=["Standard_D4s_v3"],
        storage_profile=StorageProfile(
            os_disk_image=DiskImage(source_vhd_uri="https://contoso.example/img.vhd")
        ),
        additional_properties=additional_properties,
    )

    inputs["concurrency"] = 2
    additional_properties["publisher"] = "fabrikam"

    with pytest.raises(TypeError):
        step.inputs["concurrency"] = 3
    with pytest.raises(TypeError):
        package_reference.additional_properties["publisher"] = "adatum"

    assert step.inputs == {"concurrency": 1}
    assert package_reference.additional_properties == {"publisher": "contoso"}
